func sessionOf(task string) *session.Session { return &session.Session{ID: "s-" + task, TaskID: task} }

// The equivalence tests: testdata/reads.json and artifacts.json are generated by driving the Python adapters
// (tools/gen_gateway_reads.py) over canned upstream answers. Each case here serves the same answers from an httptest
// server and requires the same requests (method, target, Accept, Authorization) and the same result, refusal or error text
// and class. A case with "go" is a place Go is deliberately stricter: the expectation is Go's, and "why" says why.

type readsFile struct {
	Token string      `json:"token"`
	Cases []readsCase `json:"cases"`
}

type readsCase struct {
	Name       string                    `json:"name"`
	Kind       string                    `json:"kind"`
	Args       map[string]any            `json:"args"`
	Routes     map[string]map[string]any `json:"routes"`
	Default    map[string]any            `json:"default"`
	Requests   []seenRequest             `json:"requests"`
	Result     any                       `json:"result"`
	Denied     *deniedJSON               `json:"denied"`
	Error      *errorJSON                `json:"error"`
	BasePath   string                    `json:"base_path"`
	Namespaces []string                  `json:"namespaces"`
	Token      *string                   `json:"token"`
	Go         *goExpect                 `json:"go"`
	Why        string                    `json:"why"`
}

type goExpect struct {
	Result   any            `json:"result"`
	Denied   *deniedJSON    `json:"denied"`
	Requests *[]seenRequest `json:"requests"`
}

type seenRequest struct {
	Method        string  `json:"method"`
	Target        string  `json:"target"`
	Accept        *string `json:"accept"`
	Authorization *string `json:"authorization"`
}

type deniedJSON struct{ Rule, Message, Hint string }

type errorJSON struct {
	Class         string `json:"class"`
	OutcomeResult string `json:"outcome_result"`
	AgentError    string `json:"agent_error"`
}

// expand turns the generator's {"$str": [before, char, n, after]} back into the long string it stands for.
func expand(v any) any {
	switch x := v.(type) {
	case map[string]any:
		if parts, ok := x["$str"].([]any); ok && len(x) == 1 {
			n, _ := parts[2].(json.Number).Int64()
			return parts[0].(string) + strings.Repeat(parts[1].(string), int(n)) + parts[3].(string)
		}
		for k, e := range x {
			x[k] = expand(e)
		}
	case []any:
		for i, e := range x {
			x[i] = expand(e)
		}
	}
	return v
}

func loadJSON(t *testing.T, name string, into any) {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("testdata", name))
	if err != nil {
		t.Fatal(err)
	}
	dec := json.NewDecoder(bytes.NewReader(b))
	dec.UseNumber()
	if err := dec.Decode(into); err != nil {
		t.Fatal(err)
	}
}

func cannedBody(b any) []byte {
	if m, ok := b.(map[string]any); ok {
		if raw, ok := m["raw"].(string); ok {
			return []byte(raw)
		}
		if rep, ok := m["repeat"].([]any); ok {
			n, _ := rep[1].(json.Number).Int64()
			p, _ := m["prefix"].(string)
			s, _ := m["suffix"].(string)
			return []byte(p + strings.Repeat(rep[0].(string), int(n)) + s)
		}
	}
	out, _ := json.Marshal(b)
	return out
}

// upstream serves a case's canned answers and records what it was asked.
type upstream struct {
	mu     sync.Mutex
	routes map[string]map[string]any
	def    map[string]any
	seen   []seenRequest
}

func (u *upstream) requests() []seenRequest {
	u.mu.Lock()
	defer u.mu.Unlock()
	return append([]seenRequest(nil), u.seen...)
}

func (u *upstream) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	u.mu.Lock()
	var accept, auth *string
	if v := r.Header.Get("Accept"); v != "" {
		accept = &v
	}
	if v := r.Header.Get("Authorization"); v != "" {
		auth = &v
	}
	u.seen = append(u.seen, seenRequest{Method: r.Method, Target: r.RequestURI, Accept: accept, Authorization: auth})
	route, ok := u.routes[r.RequestURI]
	if !ok {
		route = u.def
	}
	u.mu.Unlock()
	switch route["fail"] {
	case "URLError":
		c, _, _ := w.(http.Hijacker).Hijack()
		_ = c.Close()
		return
	case "TimeoutError":
		select {
		case <-r.Context().Done():
		case <-time.After(5 * time.Second):
		}
		return
	}
	status, _ := route["status"].(json.Number)
	code, _ := status.Int64()
	w.WriteHeader(int(code))
	_, _ = w.Write(cannedBody(route["body"]))
}

func normalize(t *testing.T, v any) any {
	t.Helper()
	b, err := json.Marshal(v)
	if err != nil {
		t.Fatal(err)
	}
	var out any
	dec := json.NewDecoder(bytes.NewReader(b))
	dec.UseNumber()
	if err := dec.Decode(&out); err != nil {
		t.Fatal(err)
	}
	return out
}

func writeCA(t *testing.T, srv *httptest.Server) string {
	t.Helper()
	p := filepath.Join(t.TempDir(), "ca.crt")
	pemBytes := pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: srv.Certificate().Raw})
	if err := os.WriteFile(p, pemBytes, 0o600); err != nil {
		t.Fatal(err)
	}
	return p
}

func TestReadBackendsEqualPython(t *testing.T) {
	var f readsFile
	loadJSON(t, "reads.json", &f)
	if len(f.Cases) < 150 {
		t.Fatalf("only %d cases: the fixture is not the one the generator writes", len(f.Cases))
	}
	n := map[string]int{}
	for _, c := range f.Cases {
		n[c.Kind]++
		switch {
		case c.Go != nil:
			n["stricter"]++
		case c.Denied != nil:
			n["denied"]++
		case c.Error != nil:
			n["error"]++
		default:
			n["result"]++
		}
		t.Run(c.Kind+"/"+c.Name, func(t *testing.T) {
			up := &upstream{routes: c.Routes, def: c.Default}
			dir := t.TempDir()
			tokFile := filepath.Join(dir, "token")
			if c.Token != nil {
				if err := os.WriteFile(tokFile, []byte(*c.Token+"\n"), 0o600); err != nil {
					t.Fatal(err)
				}
			} else {
				tokFile = filepath.Join(dir, "absent")
			}
			timeout := 5 * time.Second
			if c.Default["fail"] == "TimeoutError" {
				timeout = 150 * time.Millisecond
			}
			var got any
			var err error
			switch c.Kind {
			case "catalog":
				srv := httptest.NewServer(up)
				defer srv.Close()
				cat, e := NewCatalog(srv.URL+c.BasePath+"/", tokFile, timeout)
				if e != nil {
					t.Fatal(e)
				}
				got, err = cat.Read(context.Background(), c.Args["query"])
			case "appapi":
				srv := httptest.NewServer(up)
				defer srv.Close()
				apis, e := NewAppAPIs(map[string]string{"flight-api": srv.URL + "/", "baggage-api": srv.URL + "/v2"}, timeout)
				if e != nil {
					t.Fatal(e)
				}
				got, err = apis.Get(context.Background(), c.Args["service"], c.Args["path"])
			case "argo":
				srv := tlsServer(up)
				defer srv.Close()
				kube := &KubeReader{Server: srv.URL, TokenFile: tokFile, CAFile: writeCA(t, srv), Timeout: timeout}
				got, err = (&Argo{Kube: kube, Namespaces: c.Namespaces}).Get(context.Background(), c.Args["app"])
			default:
				t.Fatalf("kind %q", c.Kind)
			}

			wantReqs, wantResult, wantDenied := c.Requests, c.Result, c.Denied
			if c.Go != nil {
				if c.Why == "" {
					t.Fatal("a case Go answers differently says why")
				}
				wantResult, wantDenied = c.Go.Result, c.Go.Denied
				if c.Go.Requests != nil {
					wantReqs = *c.Go.Requests
				} else if c.Go.Result != nil || c.Go.Denied != nil {
					wantReqs = nil
				}
			}
			if c.Go == nil || c.Go.Requests != nil || (c.Go.Result == nil && c.Go.Denied == nil) {
				if len(wantReqs) == 0 {
					wantReqs = nil
				}
				gotReqs := up.requests()
				if len(gotReqs) == 0 {
					gotReqs = nil
				}
				if !reflect.DeepEqual(wantReqs, gotReqs) {
					t.Fatalf("requests\n want %+v\n  got %+v", wantReqs, gotReqs)
				}
			}
			switch {
			case wantDenied != nil:
				var den *core.Denied
				if !errors.As(err, &den) {
					t.Fatalf("want a refusal %+v, got %v / %v", wantDenied, got, err)
				}
				if den.Rule != wantDenied.Rule || den.Message != wantDenied.Message || den.Hint != wantDenied.Hint {
					t.Fatalf("refusal\n want %+v\n  got %+v", wantDenied, den)
				}
			case c.Error != nil && c.Go == nil:
				if err == nil {
					t.Fatalf("want error %+v, got %v", c.Error, got)
				}
				if r := dispatch.ErrorResult(err); r != c.Error.OutcomeResult {
					t.Fatalf("outcome result: want %q got %q", c.Error.OutcomeResult, r)
				}
				if m := dispatch.BackendError(err); m != c.Error.AgentError {
					t.Fatalf("agent error: want %q got %q", c.Error.AgentError, m)
				}
				if strings.Contains(dispatch.ErrorResult(err), "127.0.0.1") || strings.Contains(dispatch.ErrorResult(err), "token") {
					t.Fatalf("the evidence names an address or holds a body: %s", dispatch.ErrorResult(err))
				}
			default:
				if err != nil {
					t.Fatalf("want a result, got %v", err)
				}
				want := expand(wantResult)
				if !reflect.DeepEqual(normalize(t, want), normalize(t, got)) {
					t.Fatalf("result\n want %s\n  got %s", short(want), short(got))
				}
			}
		})
	}
	if n["catalog"] < 30 || n["appapi"] < 90 || n["argo"] < 40 || n["denied"] < 70 || n["error"] < 15 || n["result"] < 60 || n["stricter"] < 8 {
		t.Fatalf("the fixture's cases: %v", n)
	}
}

func short(v any) string {
	b, _ := json.Marshal(v)
	if len(b) > 1500 {
		return string(b[:1500]) + "..."
	}
	return string(b)
}

// -- artifacts --------------------------------------------------------------------------------------------------------

type artifactsFile struct {
	Start string       `json:"start"`
	Ops   []artifactOp `json:"ops"`
}

type artifactOp struct {
	Op      string      `json:"op"`
	Task    string      `json:"task"`
	Name    any         `json:"name"`
	Content any         `json:"content"`
	At      int64       `json:"at"`
	Micro   int64       `json:"micro"`
	Result  any         `json:"result"`
	Denied  *deniedJSON `json:"denied"`
	Go      *goExpect   `json:"go"`
	Why     string      `json:"why"`
}

// runArtifactOps replays the generated sequence against a store, through the handlers' own validation. It is shared by
// the memory store and, when a database is given, the Postgres one.
func runArtifactOps(t *testing.T, store ArtifactStore) {
	t.Helper()
	var f artifactsFile
	loadJSON(t, "artifacts.json", &f)
	start, err := time.Parse(time.RFC3339, f.Start)
	if err != nil {
		t.Fatal(err)
	}
	if len(f.Ops) < 100 {
		t.Fatalf("only %d operations", len(f.Ops))
	}
	var clock time.Time
	h, err := NewHandlers(Config{Artifacts: store, Now: func() time.Time { return clock }})
	if err != nil {
		t.Fatal(err)
	}
	for i, op := range f.Ops {
		clock = start.Add(time.Duration(op.At)*time.Second + time.Duration(op.Micro)*time.Microsecond)
		s := sessionOf(op.Task)
		var got any
		var gerr error
		switch op.Op {
		case "put":
			got, gerr = h["artifact.put"](context.Background(), s, map[string]any{"name": op.Name, "content": expand(op.Content)})
		case "get":
			var content any
			content, gerr = h["artifact.get"](context.Background(), s, map[string]any{"name": op.Name})
			got = map[string]any{"content": content}
		}
		denied, result := op.Denied, op.Result
		if op.Go != nil {
			if op.Why == "" {
				t.Fatalf("op %d: a case Go answers differently says why", i)
			}
			denied, result = op.Go.Denied, op.Go.Result
		}
		desc := op.Op + " " + short(op.Name) + " in " + op.Task
		if op.Task == "" {
			// A session with no task has no artifacts at all (Python keys them on "", shared by every such session).
			if gerr == nil {
				t.Fatalf("op %d (%s): a session with no task got %v", i, desc, got)
			}
			continue
		}
		switch {
		case denied != nil:
			var den *core.Denied
			if !errors.As(gerr, &den) || den.Rule != denied.Rule || den.Message != denied.Message || den.Hint != denied.Hint {
				t.Fatalf("op %d (%s): want refusal %+v, got %v / %v", i, desc, denied, got, gerr)
			}
		default:
			if gerr != nil {
				t.Fatalf("op %d (%s): %v", i, desc, gerr)
			}
			if !reflect.DeepEqual(normalize(t, expand(result)), normalize(t, got)) {
				t.Fatalf("op %d (%s):\n want %s\n  got %s", i, desc, short(expand(result)), short(got))
			}
		}
	}
}

func TestArtifactsEqualPythonInMemory(t *testing.T) {
	runArtifactOps(t, &MemoryArtifacts{})
}
